631				input: `{"timestamp":"0000-01-01T00:01:00+00:01","time":"0000-01-01T00:02:00+00:01","action":"a"}`,
632				ok:    false,
633			},
634		}
635		for _, tc := range cases {
636			t.Run(tc.name, func(t *testing.T) {
637				results := runNormalize(t, tc.input)
638				if tc.ok {
639					if results[0]["ok"] != true {
640						t.Fatalf("expected success, got %#v", results[0])
641					}
642					if got := eventOf(t, results[0])["timestamp"]; got != tc.want {
643						t.Fatalf("timestamp %v, want %q", got, tc.want)
644					}
645					return
646				}
647				if results[0]["ok"] != false {
648					t.Fatalf("expected failure, got %#v", results[0])
649				}
650				if _, exists := results[0]["event"]; exists {
651					t.Fatalf("failure must not emit an event")
652				}
653				msg, _ := results[0]["error"].(string)
654				if !strings.Contains(msg, FieldTimestamp) {
655					t.Fatalf("error must name %q, got %q", FieldTimestamp, msg)
656				}
657			})
658		}
659	}
660	
661	func TestNormalizeUTCYearRangeMixedStream(t *testing.T) {
662		// The year-range error is a single-line failure: surrounding legal
663		// lines still come out in order with their physical line numbers,
664		// blank lines only advance the counter, and the run reports the
665		// failure count (which drives exit status 1 in the CLI).
666		input := "{\"timestamp\":\"0000-01-01T00:01:00+00:01\",\"action\":\"a\"}\n" +
667			"\n" +
668			"{\"timestamp\":\"0000-01-01T00:00:00+00:01\",\"action\":\"b\"}\n" +
669			"   \n" +
670			"{\"timestamp\":\"9999-12-31T23:59:59-00:01\",\"action\":\"c\"}\n" +
671			"{\"timestamp\":\"9999-12-31T23:59:59Z\",\"action\":\"d\"}\n"
672		results := runNormalize(t, input)
673		if len(results) != 4 {
674			t.Fatalf("expected 4 results for 6 physical lines, got %d: %#v", len(results), results)
675		}
676		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
677			t.Fatalf("line 1 must succeed: %#v", results[0])
678		}
679		if got := eventOf(t, results[0])["timestamp"]; got != "0000-01-01T00:00:00Z" {
680			t.Fatalf("line 1 timestamp %v", got)
681		}
682		if results[1]["line"] != float64(3) || results[1]["ok"] != false {
683			t.Fatalf("line 3 must fail preserving its line number: %#v", results[1])
684		}
685		if results[2]["line"] != float64(5) || results[2]["ok"] != false {
686			t.Fatalf("line 5 must fail preserving its line number: %#v", results[2])
687		}
688		if results[3]["line"] != float64(6) || results[3]["ok"] != true {
689			t.Fatalf("legal line 6 must still be processed: %#v", results[3])
690		}
691		if eventOf(t, results[3])["action"] != "d" {
692			t.Fatalf("input order not preserved")
693		}
694	}
695	
696	// runNormalizeJSON works like runNormalize but decodes result lines with
697	// json.Number, so tests can assert that high-precision numbers in extra
698	// survive normalization verbatim instead of being rounded into float64.
699	func runNormalizeJSON(t *testing.T, input string) []map[string]any {
700		t.Helper()
701		var out bytes.Buffer
702		failures, err := NormalizeReader(strings.NewReader(input), &out)
703		if err != nil {
704			t.Fatalf("NormalizeReader returned error: %v", err)
705		}
706		results := []map[string]any{}
707		dec := json.NewDecoder(bytes.NewReader(out.Bytes()))
708		dec.UseNumber()
709		for {
710			var m map[string]any
711			if err := dec.Decode(&m); err != nil {
712				if err == io.EOF {
713					break
714				}
715				t.Fatalf("decoding result: %v", err)
716			}
717			results = append(results, m)
718		}
719		if got := countFailures(results); got != failures {
720			t.Fatalf("NormalizeReader returned %d failures but output shows %d", failures, got)
721		}
722		return results
723	}
724	
725	// runNormalizeRaw returns the exact bytes NormalizeReader wrote, for
726	// assertions on the serialized form of preserved numbers.
727	func runNormalizeRaw(t *testing.T, input string) string {
728		t.Helper()
729		var out bytes.Buffer
730		if _, err := NormalizeReader(strings.NewReader(input), &out); err != nil {
731			t.Fatalf("NormalizeReader returned error: %v", err)
732		}
733		return out.String()
734	}
735	
736	func extraOf(t *testing.T, r map[string]any) map[string]any {
737		t.Helper()
738		event := eventOf(t, r)
739		extra, ok := event["extra"].(map[string]any)
740		if !ok {
741			t.Fatalf("event has no extra object: %#v", event)
742		}
743		return extra
744	}
745	
746	// mustNumber asserts v is a JSON number whose serialized form is exactly
747	// want — no rounding, no truncation, no conversion to string.
748	func mustNumber(t *testing.T, v any, want string) {
749		t.Helper()
750		n, ok := v.(json.Number)
751		if !ok {
752			t.Fatalf("expected JSON number %s, got %T (%v)", want, v, v)
753		}
754		if n.String() != want {
755			t.Fatalf("number preserved as %q, want %q", n.String(), want)
756		}
757	}
758	
759	func TestNormalizeExtraHighPrecisionNumbers(t *testing.T) {
760		// Numbers beyond float64/int64 precision in unmapped fields must reach
761		// the event's extra with their exact literal form intact.
762		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"a",` +
763			`"big":9007199254740993,` +
764			`"neg_big":-9007199254740993,` +
765			`"precise":1.0000000000000000001,` +
766			`"huge":1e400,` +
767			`"tiny":1e-400}`
768		results := runNormalizeJSON(t, input)
769		if len(results) != 1 || results[0]["ok"] != true {
770			t.Fatalf("high-precision extra numbers must succeed, got %#v", results)
771		}
772		extra := extraOf(t, results[0])
773		mustNumber(t, extra["big"], "9007199254740993")
774		mustNumber(t, extra["neg_big"], "-9007199254740993")
775		mustNumber(t, extra["precise"], "1.0000000000000000001")
776		mustNumber(t, extra["huge"], "1e400")
777		mustNumber(t, extra["tiny"], "1e-400")
778	
779		raw := runNormalizeRaw(t, input)
780		for _, want := range []string{"9007199254740993", "1.0000000000000000001", "1e400", "1e-400"} {
781			if !strings.Contains(raw, want) {
782				t.Fatalf("serialized output must contain the exact literal %s, got %s", want, raw)
783			}
784		}
785		if strings.Contains(raw, "9007199254740992") {
786			t.Fatalf("big integer was rounded to a float64 neighbor: %s", raw)
787		}
788		if strings.Contains(raw, "Infinity") || strings.Contains(raw, "inf") {
789			t.Fatalf("out-of-float-range exponent must not serialize as infinity: %s", raw)
790		}
791	}
792	
793	func TestNormalizeExtraNestedPrecision(t *testing.T) {
794		// Precision preservation applies at every depth of unmapped objects and
795		// arrays, not just the top level; array order and the JSON types of
796		// values adjacent to the numbers must survive too.
797		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"a","payload":{` +
798			`"deep":{"id":9007199254740993},` +
799			`"list":[1.0000000000000000001,9007199254740993,"9007199254740993",true,null,3]}}`
800		results := runNormalizeJSON(t, input)
801		if results[0]["ok"] != true {
802			t.Fatalf("nested high-precision numbers must succeed, got %#v", results[0])
803		}
804		payload, ok := extraOf(t, results[0])["payload"].(map[string]any)
805		if !ok {
806			t.Fatalf("payload object must be preserved, got %#v", extraOf(t, results[0])["payload"])
807		}
808		deep, ok := payload["deep"].(map[string]any)
809		if !ok {
810			t.Fatalf("nested object level must be preserved, got %#v", payload["deep"])
811		}
812		mustNumber(t, deep["id"], "9007199254740993")
813	
814		list, ok := payload["list"].([]any)
815		if !ok || len(list) != 6 {
816			t.Fatalf("array level and length must be preserved, got %#v", payload["list"])
817		}
818		mustNumber(t, list[0], "1.0000000000000000001")
819		mustNumber(t, list[1], "9007199254740993")
820		// A string that spells a number stays a string; it is not converted.
821		if s, ok := list[2].(string); !ok || s != "9007199254740993" {
822			t.Fatalf("string-formed number must stay a string, got %T (%v)", list[2], list[2])
823		}
824		if list[3] != true {
825			t.Fatalf("adjacent boolean must keep its type, got %#v", list[3])
826		}
827		if list[4] != nil {
828			t.Fatalf("adjacent null must keep its type, got %#v", list[4])
829		}
830		mustNumber(t, list[5], "3")
831	}
832	
833	func TestNormalizeInputExtraKeepsPrecisionAndNesting(t *testing.T) {
834		// An input's own "extra" field is an ordinary unmapped field: it lands
835		// inside the output extra as one nested object, its high-precision
836		// numbers survive, and it is not flattened into the sibling fields.
837		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"a",` +
838			`"extra":{"balance":9007199254740993,"ratio":1.0000000000000000001,"tags":["x",1e400]},` +
839			`"other":2}`
840		results := runNormalizeJSON(t, input)
841		if results[0]["ok"] != true {
842			t.Fatalf("nested input extra must succeed, got %#v", results[0])
843		}
844		extra := extraOf(t, results[0])
845		if len(extra) != 2 {
846			t.Fatalf("input extra must stay one nested field, not be flattened: %#v", extra)
847		}
848		inner, ok := extra["extra"].(map[string]any)
849		if !ok {
850			t.Fatalf("input extra must be a nested object under extra, got %#v", extra["extra"])
851		}
852		mustNumber(t, inner["balance"], "9007199254740993")
853		mustNumber(t, inner["ratio"], "1.0000000000000000001")
854		tags, ok := inner["tags"].([]any)
855		if !ok || len(tags) != 2 || tags[0] != "x" {
856			t.Fatalf("nested array inside input extra not preserved: %#v", inner["tags"])
857		}
858		mustNumber(t, tags[1], "1e400")
859		if _, leaked := extra["balance"]; leaked {
860			t.Fatalf("nested extra fields must not be hoisted to the top level: %#v", extra)
861		}
862		mustNumber(t, extra["other"], "2")
863	}
864	
865	func TestNormalizeMappedFieldsStillRejectNumbers(t *testing.T) {
866		// Precision preservation is scoped to unmapped data: a number — even a
867		// legal high-precision one — in a mapped field still fails type checks.
868		cases := []struct {
869			input string
870			field string
871		}{
872			{`{"timestamp":9007199254740993,"action":"a"}`, FieldTimestamp},
873			{`{"time":1.0000000000000000001,"action":"a"}`, FieldTimestamp},
874			{`{"timestamp":"2026-01-02T00:00:00Z","action":123}`, FieldAction},
875			{`{"timestamp":"2026-01-02T00:00:00Z","event_type":1e400}`, FieldAction},
876			{`{"timestamp":"2026-01-02T00:00:00Z","action":"a","source_ip":9007199254740993}`, FieldSourceIP},
877			{`{"timestamp":"2026-01-02T00:00:00Z","action":"a","src_ip":1e400}`, FieldSourceIP},
